/// <reference types="../types/react-table-config" />

import type { VirtualItem, useVirtualizer } from '@tanstack/react-virtual';
import clsx from 'clsx';
import React, { forwardRef, useRef, useState, type CSSProperties } from 'react';
import { isElement } from 'react-is';
import {
  Cell,
  Column,
  Row,
  TableCellProps,
  TableDispatch,
  TableRowProps,
  defaultColumn,
} from 'react-table';

import { ConvertibleUnit, FormatOptions, Unit } from '@dynatrace-sdk/units';

import {
  DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID,
  DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
  DATA_TABLE_SUB_ROW_TRIGGER_ID,
} from './constants.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { getCellTypeRenderer } from '../plugins/use-column-types/useColumnTypes.js';
import { CellActionsMenu } from '../plugins/use-user-actions/components/CellActionsMenu.js';
import type { UserActionConfig } from '../plugins/use-user-actions/useUserActions.types.js';
import { isActionColumn } from '../utils/column-utils.js';

export type DataTableRowProps = {
  rowProps: Partial<TableRowProps>;
  rowStyle?: CSSProperties;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  pageRow: Row<any>;
  virtualRow: VirtualItem;
  columnVirtualizer: ReturnType<typeof useVirtualizer>;
  columnVirtualization: boolean;
  lineWrap: boolean;
  fontStyle: 'text' | 'code';
  userActions: UserActionConfig;
  dispatch: TableDispatch;
  index: number;
  tableContainerRef: React.RefObject<HTMLDivElement>;
  /** Measure callback for the virtualizer. */
  rowVirtualizerMeasureElement: (node: Element | null) => void;
  isGridLayout: boolean;
};

export type DataTableCellProps = {
  cell: Cell;
  lineWrap: boolean;
  fontStyle: 'text' | 'code';
  userActions: UserActionConfig;
  dispatch: TableDispatch;
  rowIndex: number;
  tableContainerRef: React.RefObject<HTMLDivElement>;
  virtualColumnIndex?: number;
};

type ExtendedColumn = Column & {
  formatter: FormatOptions<Unit, ConvertibleUnit>;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  Cell?: any;
};

const CellActionsTrigger = /* @__PURE__ */ forwardRef<
  HTMLButtonElement,
  {
    cell: Cell;
    cellProps: TableCellProps;
    className: string;
    cellButtonRef: React.RefObject<HTMLButtonElement>;
    virtualColumnIndex?: number;
    onClick?: () => void;
    disabled?: boolean;
  }
>(
  (
    {
      cell,
      cellProps,
      className,
      cellButtonRef,
      virtualColumnIndex,
      onClick,
      disabled,
    },
    forwardedRef,
  ) => {
    const { role, ref, ...cellPropsWithoutRole } = cellProps;
    const triggerProps = onClick
      ? _mergeProps(cellPropsWithoutRole, { onClick })
      : cellPropsWithoutRole;

    const mergedRefs = useMergeRefs([forwardedRef, cellButtonRef, ref]);

    if (virtualColumnIndex) {
      triggerProps.style = {
        ...triggerProps.style,
        gridColumnStart: virtualColumnIndex + 1,
      };
    }
    // Note: ignore remainingProps from Menu.Trigger on purpose here, otherwise the menu would not open
    return (
      <button
        {...triggerProps}
        disabled={disabled}
        className={className}
        role="cell"
        ref={mergedRefs}
      >
        <div>{cell.render('Cell')}</div>
      </button>
    );
  },
);

(
  CellActionsTrigger as typeof CellActionsTrigger & { displayName: string }
).displayName = 'CellActionsTrigger';

const DataTableCell = ({
  cell,
  lineWrap,
  fontStyle,
  userActions,
  dispatch,
  rowIndex,
  tableContainerRef,
  virtualColumnIndex,
}: DataTableCellProps) => {
  const {
    id: columnId,
    lineWrap: columnLineWrap,
    fontStyle: columnFontStyle,
  } = cell.column;

  // ref for action cell button
  const cellButtonRef = useRef<HTMLButtonElement>(null);

  // extend the column to check if it has formatters
  const extendedColumn = cell.column as Column as ExtendedColumn;

  const isCellSubRows = columnId === DATA_TABLE_SUB_ROW_TRIGGER_ID;
  const isCellExpandable = columnId === DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID;
  const isPrefixCell =
    columnId === DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID ||
    isCellExpandable ||
    isCellSubRows;
  const isCellInActionColumn = isActionColumn(columnId);

  // check if we have columnType defined which will have DataTable built in renderer or use defaultColumn
  const defaultCellRenderer = cell.column.columnType
    ? getCellTypeRenderer(cell.column.columnType)
    : defaultColumn.Cell;

  // if column is custom or has a formatter or the renderer is an in built, then it cannot be custom rendering
  const isCustomRendering =
    !isPrefixCell &&
    !extendedColumn.formatter &&
    cell.column.Cell &&
    cell.column.Cell !== defaultCellRenderer;

  const isLineWrapped = columnLineWrap ?? lineWrap;
  const cellFontStyle = columnFontStyle ?? fontStyle;
  const className = clsx('strato-table-cell', {
    'strato-table-cell-sorted': cell.column.isSorted,
    'strato-table-cell-line-wrap': isLineWrapped,
    'strato-table-cell-text-style': cellFontStyle === 'text',
    'strato-table-cell-code-style': cellFontStyle === 'code',
    'strato-table-cell-sparkline': cell.column.columnType === 'sparkline',
    'strato-table-cell-alignment-left': cell.column.alignment === 'left',
    'strato-table-cell-alignment-center': cell.column.alignment === 'center',
    'strato-table-cell-alignment-right': cell.column.alignment === 'right',
    'strato-table-cell-alignment-top-left':
      cell.column.alignment === 'top-left',
    'strato-table-cell-alignment-top-center':
      cell.column.alignment === 'top-center',
    'strato-table-cell-alignment-top-right':
      cell.column.alignment === 'top-right',
    'strato-table-cell-alignment-bottom-left':
      cell.column.alignment === 'bottom-left',
    'strato-table-cell-alignment-bottom-center':
      cell.column.alignment === 'bottom-center',
    'strato-table-cell-alignment-bottom-right':
      cell.column.alignment === 'bottom-right',
    'strato-table-prefix-cell': isPrefixCell,
    'strato-table-cell-expandable': isCellExpandable,
    'strato-table-cell-sub-rows': isCellSubRows,
    'strato-table-cell-custom-render': isCustomRendering,
    'strato-table-cell-for-actions': isCellInActionColumn,
  });

  const cellActionsProvider =
    userActions.cellActionProviders[columnId] ??
    userActions.defaultCellActionProvider;
  // Cell actions are not rendered for the expandable/selectable/action columns
  const cellActions =
    isPrefixCell || isCellInActionColumn ? null : cellActionsProvider;

  const [menuOpen, setMenuOpen] = useState(false);

  const modifiedCellProps = { ...cell.getCellProps() };

  if (modifiedCellProps.style && isPrefixCell) {
    // remove any styles that affect width, minWidth, and maxWidth for expandable/selectable/subrows cells
    const { flex, width, minWidth, maxWidth, ...cellStyle } =
      modifiedCellProps.style;

    modifiedCellProps.style = cellStyle;
  }

  if (virtualColumnIndex) {
    modifiedCellProps.style = {
      ...modifiedCellProps.style,
      gridColumnStart: virtualColumnIndex + 1,
    };
  }

  if (cellActions === null) {
    return (
      <div {...modifiedCellProps} className={className}>
        <div style={{ width: '100%' }}>
          {cell.render('Cell', { currentRowIndex: rowIndex })}
        </div>
      </div>
    );
  }

  const { column, row } = cell;
  const { config, ...remainingColumnProps } = column;

  if (menuOpen) {
    // for performance, only call cellActions inside the if(menuOpen)
    const tableUserActions = cellActions({
      column: remainingColumnProps,
      row: { ...row },
      cell: { value: cell.value },
    });

    return (
      <CellActionsMenu
        trigger={
          <CellActionsTrigger
            cell={cell}
            cellProps={modifiedCellProps}
            className={className}
            cellButtonRef={cellButtonRef}
            virtualColumnIndex={virtualColumnIndex}
          />
        }
        cell={cell}
        tableUserActions={tableUserActions}
        dispatch={dispatch}
        cellButtonRef={cellButtonRef}
        tableContainerRef={tableContainerRef}
        onClose={() => {
          setMenuOpen(false);
        }}
      />
    );
  }

  return (
    <CellActionsTrigger
      cell={cell}
      cellProps={modifiedCellProps}
      className={className}
      cellButtonRef={cellButtonRef}
      virtualColumnIndex={virtualColumnIndex}
      onClick={() => {
        // for performance, only do the following inside onClick
        const tableUserActions = cellActions({
          column: remainingColumnProps,
          row: { ...row },
          cell: { value: cell.value },
        });

        const hasActions =
          isElement(tableUserActions) &&
          React.Children.count(tableUserActions.props.children);

        if (hasActions) {
          setMenuOpen(true);
        }
      }}
    />
  );
};

(DataTableCell as typeof DataTableCell & { displayName: string }).displayName =
  'DataTableCell';

export const DataTableRow = ({
  rowProps,
  rowStyle,
  pageRow,
  virtualRow,
  columnVirtualizer,
  lineWrap,
  fontStyle,
  userActions,
  index: rowIndex,
  dispatch,
  tableContainerRef,
  rowVirtualizerMeasureElement,
  isGridLayout,
  columnVirtualization,
}: DataTableRowProps) => {
  // removing minWidth from the row style as its interfering with how row grows or shrinks
  const { minWidth, ...updatedRowStyle } = rowStyle ?? {};
  // this will simplify even-rows for zebraStripes based virtualization and expansion
  const isEven = rowIndex % 2 !== 0;

  const virtualColumns = columnVirtualizer.getVirtualItems();

  let translateX = '';
  let rowWidth = '100%';
  if (columnVirtualization && !isGridLayout && virtualColumns[0]?.start > 0) {
    translateX = `translateX(${virtualColumns[0]?.start}px)`;
    rowWidth = `calc(100% - ${virtualColumns[0].start}px)`;
  }

  return (
    <div
      {...rowProps}
      className={clsx('strato-table-row', {
        'strato-table-row-even': isEven,
        'strato-table-row-expanded': pageRow.isRowExpanded,
      })}
      ref={rowVirtualizerMeasureElement}
      data-index={virtualRow.index}
      aria-rowindex={rowIndex + 1}
      style={
        {
          ...updatedRowStyle,
          position: 'absolute',
          top: 0,
          left: 0,
          transform: `translateY(${virtualRow.start}px) ${translateX}`,
          minWidth: rowWidth,
        } as React.CSSProperties
      }
    >
      {columnVirtualization
        ? virtualColumns.map((virtualColumn: VirtualItem) => (
            <DataTableCell
              key={virtualColumn.key}
              cell={pageRow.cells[virtualColumn.index]}
              lineWrap={lineWrap}
              fontStyle={fontStyle}
              userActions={userActions}
              dispatch={dispatch}
              rowIndex={rowIndex}
              tableContainerRef={tableContainerRef}
              virtualColumnIndex={virtualColumn.index}
            />
          ))
        : pageRow.cells.map((cell, index) => (
            <DataTableCell
              key={`strato-table-cell-${pageRow.index}-${index}`}
              cell={cell}
              lineWrap={lineWrap}
              fontStyle={fontStyle}
              userActions={userActions}
              dispatch={dispatch}
              rowIndex={rowIndex}
              tableContainerRef={tableContainerRef}
            />
          ))}
    </div>
  );
};

(DataTableRow as typeof DataTableRow & { displayName: string }).displayName =
  'DataTableRow';
